KEEP_TABLES = {"users", "documents", "chunks"}


# ---------------------------------------------------------------------------------------------------------------------
# Featured stories -> simulator scenarios (day index 59 = today)
# ---------------------------------------------------------------------------------------------------------------
def _scenario(story: str, r: random.Random, c12: int) -> S.Scenario:
    last = DAYS - 1
    sc = S.Scenario(random_events=False, home_episodes=story != "good")
    # crises inside the 60-day window (at most 2, never in the last 10 days) so trend charts show some history
    for k in range(min(c12, 2) if story != "good" else 0):
        day = r.randint(6, 22) if k == 0 else r.randint(28, 46)
        sc.events.append({"day": day, "severity": r.choice(["moderate", "severe"]),
                          "hospitalised": r.random() < 0.6, "prodrome": 3})
    if story == "rising":
        sc.bad_days = set(range(last - 4, last + 1))
        sc.events.append({"day": last + 2, "severity": "moderate", "prodrome": 3, "intensity": 1.3})
    elif story == "critical":
        sc.bad_days = set(range(last - 3, last + 1))
        sc.infection_days = set(range(last - 3, last + 1))
        sc.fever = {last - 1: 38.0, last: 38.7}
        sc.events.append({"day": last + 1, "severity": "severe", "prodrome": 3, "intensity": 1.8,
                          "infection": True})
    elif story == "nonadherent":
        sc.missed_hu_days = set(range(last - 9, last + 1))
        sc.bad_days = set(range(last - 5, last + 1))
        sc.events.append({"day": last + 3, "severity": "moderate", "prodrome": 3, "intensity": 1.0})
    elif story == "cold":
        sc.cold_days = set(range(last - 2, last + 1))
        sc.bad_days = {last - 1, last}
    elif story == "fever":
        sc.infection_days = set(range(last - 2, last + 1))
        sc.fever = {last - 1: 38.1, last: 38.6}
    elif story == "steady":
        sc.bad_days = {d for d in range(DAYS) if r.random() < 0.08 and d < last - 2}
    return sc


def _imaging_for(name: str, pid: str, today: date) -> list[dict]:
    """Fictional radiology history that fits each story."""
    d = lambda days: today - timedelta(days=days)  # noqa: E731
    st = S.imaging_study
    return {
        "Ama Owusu": [st(pid, "cxr_normal", d(150), indication="Cough and chest tightness during a crisis."),
                      st(pid, "us_abdomen", d(400), spleen=False, stones=True, ss=True)],
        "Kwame Mensah": [st(pid, "cxr_acs", d(430), side="right lower"),
                         st(pid, "us_abdomen", d(700), spleen=False, stones=True, ss=True),
                         st(pid, "cxr_normal", d(200))],
        "Efua Asante": [st(pid, "mri_brain_normal", d(800))],
        "Kofi Boateng": [st(pid, "mri_hip_avn", d(240), side="left"),
                         st(pid, "us_abdomen", d(500), spleen=True, stones=False)],
        "Abena Darko": [st(pid, "us_abdomen", d(320), spleen=False, stones=False, ss=True)],
        "Yaw Adjei": [st(pid, "tcd", d(45), velocity=176, vessel="right MCA"),
                      st(pid, "tcd", d(410), velocity=158, vessel="left MCA"),
                      st(pid, "tcd", d(780), velocity=149, vessel="left MCA")],
        "Kojo Appiah": [st(pid, "cxr_acs", d(250), side="bilateral lower"),
                        st(pid, "mri_brain_sci", d(600)),
                        st(pid, "mri_hip_avn", d(120), side="right")],
        "Adwoa Ofori": [st(pid, "us_abdomen", d(90), spleen=True, stones=False)],
        "Esi Quaye": [st(pid, "cxr_normal", d(60), indication="Fever and cough; exclude pneumonia.")],
        "Nana Agyeman": [st(pid, "cxr_acs", d(520), side="left lower"), st(pid, "mri_brain_normal", d(900))],
    }.get(name, [])


def _history(spec: S.Spec, c12: int, in_window: int, start: date, r: random.Random) -> list[dict]:
    """Crises before the 60-day window: c12 in the last 12 months in total, plus some in the year before."""
    out = []
    today = start + timedelta(days=DAYS - 1)
    for k in range(max(0, c12 - in_window)):
        out.append(today - timedelta(days=r.randint(DAYS + 5, 360)))
    for k in range(max(0, round(c12 * 0.8 + r.uniform(-0.5, 0.5)))):
        out.append(today - timedelta(days=r.randint(370, 725)))
    rows = []
    for d0 in sorted(out):
        sev = r.choice(["mild", "moderate", "severe"])
        hosp = r.random() < {"mild": 0.25, "moderate": 0.6, "severe": 0.95}[sev]
        rows.append({"patient_id": spec.id, "date": d0, "severity": sev, "hospitalised": hosp,
                     "los_days": float(r.randint(2, 7)) if hosp else None, "facility": spec.facility,
                     "notes": "Vaso-occlusive crisis (demo)"})
    return rows


async def _bulk(s, model, rows: list[dict], chunk: int = 5000) -> None:
    for i in range(0, len(rows), chunk):
        await s.execute(insert(model), rows[i:i + chunk])


def _at(day: date, h: int = 8, m: int = 30) -> datetime:
    return datetime.combine(day, time(h, m), tzinfo=UTC)


def _assessment_row(pid: str, day: date, res: risk.Result, created: datetime, flags: bool = False) -> dict:
    return {"id": new_id(), "patient_id": pid, "kind": "checkin", "for_date": day, "score": res.score,
            "level": res.level, "probability": res.probability, "factors": res.factors,
            "red_flags": res.red_flags if flags else [], "summary": None, "plan": care.rule_plan(res), "sources": [],
            "model_version": res.model_version, "created_at": created}


# ---------------------------------------------------------------------------------------------------------------------
async def _seed_featured(s, today: date) -> list[Patient]:
    r = random.Random(42)
    nr = np.random.default_rng(42)
    start = today - timedelta(days=DAYS - 1)
    now = datetime.now(UTC)
    teams = ["Haematology A (Dr. Owusu-Ansah)", "Haematology B (Dr. Tetteh)"]
    created = []
    for n, (name, sex, age, gt, hu, hb0, hbf, c12, story, region) in enumerate(PATIENTS):
        district, facility = S.REGION[region][3][0]
        spec = S.sample_spec(nr, start, n, region=region, genotype=gt, age=age + r.uniform(0.05, 0.8), sex=sex)
        spec.name, spec.on_hu, spec.hb_baseline = name, hu, hb0
        spec.hbf, spec.hbf_known = (hbf if hbf is not None else 3.0), hbf is not None
        spec.hu_since = start - timedelta(days=400) if hu else None
        spec.adherence = 0.9 if hu else spec.adherence
        spec.devices = tuple(k for k, _, _ in DEVICES)
        spec.device_missing, spec.checkin_rate, spec.has_labs = 0.04, 0.9, True
        spec.lab_interval = r.randint(14, 56)
        spec.history, spec.featured = {}, True
        spec.district, spec.facility = district, facility
        p = Patient(mrn=f"KBTH-{10231 + n * 17}", name=name, sex=sex, genotype=gt, on_hydroxyurea=hu,
                    date_of_birth=spec.dob, hb_baseline=hb0, hbf_percent=hbf, crises_12m=c12,
                    phone=f"+233 24 {r.randint(100, 999)} {r.randint(1000, 9999)}", care_team=teams[n % 2],
                    notes="Fictional demo patient.", region=region, district=district, facility=facility,
                    featured=True)
        s.add(p)
        await s.flush()
        spec.id = p.id
        sc = _scenario(story, r, c12)
        sim = S.simulate(spec, start, DAYS, nr, sc)
        a = sim.a
        a["checkin"][DAYS - 6:] = True                       # engaged recently (stories need today's check-in)
        if story == "critical":                             # Kwame today: brewing crisis with chest symptoms
            a["chest"][DAYS - 1] = True
        checkins = sim.checkins()
        last = checkins[-1]
        if story == "critical":
            last.update(pain=8, temperature_c=38.7, infection_symptoms=True, chest_symptoms=True, spo2=91.0)
        if story == "fever":
            last.update(temperature_c=38.6, pain=max(5, last["pain"]))
        # devices + readings
        dev_ids = {}
        for kind, label, code in DEVICES:
            d = Device(patient_id=p.id, kind=kind, label=label, vendor="Sample (simulated)",
                       serial=f"SIM-{code}-{r.randint(10000, 99999)}", status="active", simulated=True,
                       battery=r.randint(35, 100), last_seen=now - timedelta(minutes=r.randint(2, 50)))
            s.add(d)
            await s.flush()
            dev_ids[kind] = d.id
        readings = [x for x in sim.readings(dev_ids, nr) if x["ts"] <= now]
        if story == "critical":   # thermometer 38.7 and >= 15 min of SpO2 < 92 % on the oximeter this morning
            for k, v in enumerate((91.0, 90.0, 89.0, 90.0)):
                readings.append({"device_id": dev_ids["pulse_oximeter"], "patient_id": p.id,
                                 "ts": now - timedelta(minutes=95 - 10 * k), "metric": "spo2", "value": v})
            readings.append({"device_id": dev_ids["thermometer"], "patient_id": p.id,
                             "ts": now - timedelta(minutes=70), "metric": "body_temp_c", "value": 38.7})
        if story == "fever":
            readings.append({"device_id": dev_ids["thermometer"], "patient_id": p.id,
                             "ts": now - timedelta(minutes=40), "metric": "body_temp_c", "value": 38.6})
        labs = list(sim.lab_rows)
        bad = sorted(sc.bad_days | set(sc.fever))
        for t in bad:                                        # bloods taken around bad days (and today if unwell)
            if t == bad[-1] or t % 5 == 0:
                when = _at(start + timedelta(days=t), 10, 15)
                for code in ("hb", "wbc", "retic", "ldh", "crp"):
                    labs.append(S.lab_row(p.id, when, code, S._lab_value(sim, code, t, nr)))
        labs = [x for x in labs if x["taken_at"] <= now]
        imaging = _imaging_for(name, p.id, today) + [x for x in sim.imaging_rows]
        in_window = [c for c in sim.crises() if c["date"] >= start]
        crises = _history(spec, c12, len(in_window), start, r) + in_window
        await _bulk(s, CheckIn, [dict(c) for c in checkins])
        await _bulk(s, Reading, readings)
        await _bulk(s, LabResult, [{"id": new_id(), **x} for x in labs])
        await _bulk(s, ImagingStudy, [{"id": new_id(), **x} for x in imaging])
        await _bulk(s, Crisis, [{"id": new_id(), **x} for x in crises])
        # daily assessment history (same feature code, as of each past day; device data from daily aggregates)
        rec = features.Records.from_rows(p, checkins=checkins, readings=readings, labs=labs, imaging=imaging,
                                         crises=crises)
        rows = []
        for c in checkins:
            day = c["date"]
            i = (day - start).days
            if 2 < i < DAYS - 1:
                res = risk.assess_records(rec, as_of=day)
                rows.append(_assessment_row(p.id, day, res, _at(day)))
        await _bulk(s, Assessment, rows)
        created.append(p)
    await s.flush()
    for p in created:                                        # today's score from the database, like the app does
        res = await care.score_patient(s, p)
        await care.save_assessment(s, p, res, "checkin")
    return created


async def _seed_registry(s, today: date, n: int) -> None:
    """Wider synthetic registry for the policy dashboard: 24 months of crises from the simulator, latest check-ins,
    labs, imaging and a latest assessment."""
    if n <= 0:
        return
    t0 = _time.time()
    start = today - timedelta(days=729)
    nr = np.random.default_rng(2024)
    now = datetime.now(UTC)
    P, CI, CR, LB, IM, AS = [], [], [], [], [], []
    for i in range(n):
        spec = S.sample_spec(nr, start, 1000 + i)
        spec.id = new_id()
        sim = S.simulate(spec, start, 730, nr, S.Scenario(random_events=True))
        crises = [c for c in sim.crises() if c["date"] >= start]
        row = sim.patient_row()
        c12 = sum(1 for c in crises if (today - c["date"]).days < 365)
        P.append({**row, "id": spec.id, "mrn": f"GH-{S.REGIONS.index(S.REGION[spec.region]) + 1:02d}-{100000 + i}",
                  "crises_12m": c12, "featured": False, "phone": "", "notes": "Synthetic registry record.",
                  "care_team": f"SCD clinic, {spec.facility}", "created_at": now})
        checkins = sim.checkins()[-14:]
        checkins = [c for c in checkins if (today - c["date"]).days < 14]
        labs = sim.lab_rows
        latest = {}
        for x in labs:
            if x["taken_at"].date() <= today:
                latest[x["code"]] = x
        imaging = [x for x in sim.imaging_rows if x["study_date"] <= today]
        CI += checkins
        CR += [{"id": new_id(), **c} for c in crises]
        LB += [{"id": new_id(), **x} for x in latest.values()]
        IM += [{"id": new_id(), **x} for x in imaging]
        rec = features.Records.from_rows(row | {"crises_12m": c12}, checkins=checkins, labs=list(latest.values()),
                                         imaging=imaging, crises=crises)
        res = risk.assess_records(rec, as_of=today)
        AS.append(_assessment_row(spec.id, today, res, now - timedelta(minutes=int(nr.integers(5, 600))), True))
    await _bulk(s, Patient, P)
    await _bulk(s, CheckIn, CI)
    await _bulk(s, Crisis, CR)
    await _bulk(s, LabResult, LB)
    await _bulk(s, ImagingStudy, IM)
    await _bulk(s, Assessment, AS)
    log.info("Seeded registry: %d patients, %d crises (%.1fs)", n, len(CR), _time.time() - t0)


async def ensure_demo_users(s) -> None:
    """Demo accounts when DEMO_PASSWORD is set; the patient account always points at the current Ama Owusu."""
    pw = get_settings().demo_password
    if not pw:
        return
    from app.security import hash_password
    ama = await s.scalar(select(Patient).where(Patient.name == "Ama Owusu", Patient.featured.is_(True)).limit(1))
    for email, name, role in DEMO_USERS:
        u = await s.scalar(select(User).where(User.email == email))
        if u is None:
            s.add(User(email=email, name=name, role=role, password_hash=hash_password(pw),
                       patient_id=ama.id if role == "patient" and ama else None))
        elif role == "patient" and ama and u.patient_id != ama.id:
            u.patient_id = ama.id
    await s.commit()


def registry_size() -> int:
    v = os.environ.get("SEED_REGISTRY_PATIENTS")
    if v is not None:
        return max(0, int(v))
    return 1500 if get_settings().uses_postgres else 0


async def seed() -> bool:
    async with open_session() as s:
        if await s.scalar(select(func.count()).select_from(Patient)):
            await ensure_demo_users(s)
            return False
        t0 = _time.time()
        today = date.today()
        await _seed_featured(s, today)
        await s.commit()
        await _seed_registry(s, today, registry_size())
        await s.commit()
        await ensure_demo_users(s)
        log.info("Seeded demo data in %.1fs", _time.time() - t0)
    return True


async def reset() -> None:
    """Dev only: delete all data except users, documents and chunks."""
    if get_settings().is_production:
        raise SystemExit("Refusing to reset a production database.")
    async with open_session() as s:
        for table in reversed(Base.metadata.sorted_tables):
            if table.name not in KEEP_TABLES:
                await s.execute(delete(table))
        await s.execute(User.__table__.update().where(User.role == "patient").values(patient_id=None))
        await s.commit()


async def _main(do_reset: bool) -> None:
    from app import db
    await db.create_tables()
    if do_reset:
        await reset()
        log.info("Wiped data tables (kept users, documents, chunks)")
    done = await seed()
    log.info("Seeded" if done else "Database already has patients: nothing to do (use --reset in development)")
    await db.dispose()


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description="Seed SickleGuard demo data (fictional).")
    ap.add_argument("--reset", action="store_true", help="dev only: wipe data tables (not users/documents) first")
    logging.basicConfig(level=logging.INFO, format="%(levelname)s %(name)s: %(message)s")
    asyncio.run(_main(ap.parse_args().reset))
